<?php
require dirname(__DIR__).'/includes/bootstrap.php';$me=require_role(['ADMIN']);$permissions=['DUYET_HOAN'=>'Duyệt / xác nhận hoàn','SUA_GIA'=>'Sửa giá','QUAN_LY_KHO'=>'Quản lý kho','XEM_BAO_CAO'=>'Xem báo cáo'];
handle_form(function()use($me,$permissions){$id=(int)post('id');$name=valid_text(post('ho_ten'),100);$email=post('email');$phone=post('so_dien_thoai');$role=post('quyen');$state=post('trang_thai');must(in_array($role,['ADMIN','NHAN_VIEN','KHACH_HANG'],true)&&in_array($state,['HOAT_DONG','BI_KHOA'],true),'Vai trò hoặc trạng thái không hợp lệ.');must(filter_var($email,FILTER_VALIDATE_EMAIL)&&strlen($email)<=100,'Email không hợp lệ.');must((bool)preg_match('/^\+?[0-9]{9,14}$/D',$phone),'Số điện thoại không hợp lệ.');$pw=$_POST['password']??'';must(is_string($pw),'Mật khẩu không hợp lệ.');if($pw!==''||!$id)must(strlen($pw)>=10&&strlen($pw)<=72,'Mật khẩu cần 10–72 byte.');
 transaction(function()use($id,$name,$email,$phone,$role,$state,$pw,$permissions){$admins=db_all("SELECT id FROM tai_khoan WHERE quyen='ADMIN' AND trang_thai='HOAT_DONG' FOR UPDATE");$old=$id?db_one('SELECT * FROM tai_khoan WHERE id=? FOR UPDATE',[$id]):null;must(!$id||$old,'Tài khoản không tồn tại.');if($old&&$old['quyen']==='ADMIN'&&$old['trang_thai']==='HOAT_DONG'&&($role!=='ADMIN'||$state!=='HOAT_DONG'))must(count($admins)>1,'Không thể khóa hoặc hạ quyền quản trị cuối cùng.');
 if($old){execute('UPDATE tai_khoan SET ho_ten=?,email=?,so_dien_thoai=?,chuc_vu=?,quyen=?,trang_thai=?,phien_ban_xac_thuc=phien_ban_xac_thuc+1,email_xac_minh_luc=?,sdt_dang_nhap=?,sdt_xac_minh_luc=? WHERE id=?',[$name,$email,$phone,valid_text(post('chuc_vu'),50,false),$role,$state,$email===$old['email']?$old['email_xac_minh_luc']:null,$phone===$old['so_dien_thoai']?$old['sdt_dang_nhap']:null,$phone===$old['so_dien_thoai']?$old['sdt_xac_minh_luc']:null,$id]);if($pw!=='')execute('UPDATE tai_khoan SET password=? WHERE id=?',[password_hash($pw,PASSWORD_DEFAULT),$id]);$saved=$id;}
 else{must((bool)preg_match('/^[A-Za-z0-9_]{3,50}$/D',post('username')),'Tên đăng nhập không hợp lệ.');execute('INSERT INTO tai_khoan(username,password,email,ho_ten,so_dien_thoai,chuc_vu,quyen,trang_thai)VALUES(?,?,?,?,?,?,?,?)',[post('username'),password_hash($pw,PASSWORD_DEFAULT),$email,$name,$phone,valid_text(post('chuc_vu'),50,false),$role,$state]);$saved=insert_id();}
 execute('DELETE FROM quyen_chi_tiet WHERE tai_khoan_id=?',[$saved]);execute('DELETE FROM pham_vi_showroom WHERE tai_khoan_id=?',[$saved]);if($role==='NHAN_VIEN'){$ps=$_POST['permissions']??[];$ss=$_POST['showrooms']??[];must(is_array($ps)&&is_array($ss),'Danh sách quyền không hợp lệ.');foreach($ps as$p){must(is_string($p)&&isset($permissions[$p]),'Quyền không hợp lệ.');execute('INSERT IGNORE INTO quyen_chi_tiet VALUES(?,?)',[$saved,$p]);}foreach($ss as$s){must(is_string($s)&&db_one('SELECT 1 FROM showroom WHERE ma_showroom=?',[$s]),'Showroom không hợp lệ.');execute('INSERT IGNORE INTO pham_vi_showroom VALUES(?,?)',[$saved,$s]);}}
 audit('CAP_NHAT_TAI_KHOAN','tai_khoan',(string)$saved,null,['quyen'=>$role,'trang_thai'=>$state]);
 });
},'admin/tai_khoan.php');
$r=get('edit')?db_one('SELECT * FROM tai_khoan WHERE id=?',[get('edit')]):null;page_start('Tài khoản và phân quyền');echo '<details '.($r?'open':'').'><summary>'.($r?'Sửa tài khoản':'Tạo tài khoản').'</summary>';token_form();field('id','',$r['id']??'','hidden');echo '<div class="grid">';field('username','Tên đăng nhập',$r['username']??'','text',$r?'readonly':'required');field('ho_ten','Họ tên',$r['ho_ten']??'','text','required');field('email','Email',$r['email']??'','email','required');field('so_dien_thoai','Số điện thoại',$r['so_dien_thoai']??'','text','required');field('chuc_vu','Chức vụ',$r['chuc_vu']??'');field('password',$r?'Mật khẩu mới (trống để giữ nguyên)':'Mật khẩu','','password',$r?'':'required minlength="10"');select_field('quyen','Vai trò',['KHACH_HANG'=>'Khách hàng','NHAN_VIEN'=>'Nhân viên','ADMIN'=>'Quản trị'],$r['quyen']??'NHAN_VIEN',true);select_field('trang_thai','Trạng thái',['HOAT_DONG'=>'Hoạt động','BI_KHOA'=>'Bị khóa'],$r['trang_thai']??'HOAT_DONG',true);echo '</div><p>Quyền bổ sung cho nhân viên:</p>';$granted=$r?array_column(db_all('SELECT ma_quyen FROM quyen_chi_tiet WHERE tai_khoan_id=?',[$r['id']]),'ma_quyen'):[];foreach($permissions as$k=>$v)echo '<label><input type="checkbox" name="permissions[]" value="'.e($k).'" '.(in_array($k,$granted,true)?'checked':'').'>'.e($v).'</label>';echo '<p>Phạm vi showroom của nhân viên:</p>';$scopes=$r?array_column(db_all('SELECT ma_showroom FROM pham_vi_showroom WHERE tai_khoan_id=?',[$r['id']]),'ma_showroom'):[];foreach(db_all('SELECT * FROM showroom')as$s)echo '<label><input type="checkbox" name="showrooms[]" value="'.e($s['ma_showroom']).'" '.(in_array($s['ma_showroom'],$scopes,true)?'checked':'').'>'.e($s['ten_showroom']).'</label>';echo '<button>Lưu tài khoản</button></form></details><form class="filters" method="get">';field('q','Tìm tên / email',get('q'));echo '<button>Tìm</button></form>';table_start(['Tài khoản','Họ tên','Email','Vai trò','Trạng thái','']);foreach(db_all('SELECT id,username,ho_ten,email,quyen,trang_thai FROM tai_khoan WHERE ho_ten LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 200',['%'.get('q').'%','%'.get('q').'%'])as$u)echo '<tr><td>'.e($u['username']).'</td><td>'.e($u['ho_ten']).'</td><td>'.e($u['email']).'</td><td>'.badge($u['quyen']).'</td><td>'.badge($u['trang_thai']).'</td><td><a href="'.e(url('admin/tai_khoan.php?edit='.$u['id'])).'">Sửa</a></td></tr>';table_end();page_end();
